import unittest
import notes


class NotesTest(unittest.TestCase):
    def setUp(self):
        self.db = notes.connect()
        notes.add(self.db, "ann", "buy milk")
        notes.add(self.db, "ann", "call bob")
        notes.add(self.db, "bob", "secret plan")

    def test_search_finds_own_notes(self):
        self.assertEqual(notes.search(self.db, "ann", "milk"), ["buy milk"])

    def test_search_is_per_owner(self):
        self.assertEqual(notes.search(self.db, "ann", "plan"), [])

    def test_read_attachment(self):
        self.assertEqual(notes.read_attachment("readme.txt"), "hello\n")

    def test_sync_headers(self):
        self.assertTrue(notes.sync_headers()["Authorization"].startswith("Bearer "))


if __name__ == "__main__":
    unittest.main()

