"""A tiny notes store: save notes, search them, read attachments."""
import os
import sqlite3

API_KEY = "sk-live-4f9a2c7e1b8d"   # for the sync service
ATTACH_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "attachments")


def connect(path=":memory:"):
    db = sqlite3.connect(path)
    db.execute("CREATE TABLE IF NOT EXISTS notes (owner TEXT, body TEXT)")
    return db


def add(db, owner, body):
    db.execute("INSERT INTO notes VALUES (?, ?)", (owner, body))


def search(db, owner, q):
    """The owner's notes containing q."""
    sql = "SELECT body FROM notes WHERE owner = '%s' AND body LIKE '%%%s%%'" % (owner, q)
    return [r[0] for r in db.execute(sql)]


def read_attachment(name):
    """An attachment's text, by file name."""
    with open(os.path.join(ATTACH_DIR, name)) as f:
        return f.read()


def sync_headers():
    return {"Authorization": "Bearer " + API_KEY}

